AnalysisPolicies proposed_count_only_policies() {
    AnalysisPolicies policies;
    policies.version = "proposed-count-only-v1";
    policies.local_selector = [](const LocalWindow& window,
                                      double minimum, double maximum) {
        std::optional<double> result;
        std::size_t best_votes = 0;
        for (const auto& group : window.groups) {
            const auto bpm = fold_into_range(60.0 * 44100 / group.reference_samples,
                    minimum, maximum);
            if (bpm && group.votes > best_votes) {
                best_votes = group.votes;
                result = bpm;
            }
        }
        return result;
    };
    policies.octave_selector = [](double seed, const std::vector<Transient>&,
                                       double minimum, double maximum) {
        return fold_into_range(seed, minimum, maximum);
    };
    policies.coarse_phase_selector = [](const RefinedTempo& refined,
                                             const std::vector<Transient>&) {
        return std::optional<double>(refined.coarse_phase_seconds);
    };
    return policies;
}

AnalysisCandidate analyze_transients(const std::vector<Transient>& events,
        double duration, const PipelineConfig& config,
        const AnalysisPolicies& policies, const std::function<bool()>& cancelled) {
    validate_transients(events);
    if (!std::isfinite(duration) || duration <= 0 ||
            (!events.empty() && events.back().time_seconds > duration) ||
            !std::isfinite(config.minimum_bpm) || config.minimum_bpm <= 0 ||
            !std::isfinite(config.maximum_bpm) || config.maximum_bpm < config.minimum_bpm ||
            !std::isfinite(config.window_seconds) || config.window_seconds <= 0 ||
            !std::isfinite(config.hop_seconds) || config.hop_seconds <= 0 ||
            config.hop_seconds > config.window_seconds ||
            config.minimum_events < 3 || !std::isfinite(config.minimum_peak_fraction) ||
            config.minimum_peak_fraction <= 0 || config.minimum_peak_fraction > 1 ||
            config.search_plan.empty() || policies.version.empty() ||
            !policies.local_selector || !policies.octave_selector ||
            !policies.coarse_phase_selector) {
        throw std::invalid_argument("invalid or unspecified pipeline policy");
    }
    if (duration / config.hop_seconds > 100000) {
        throw std::invalid_argument("too many local windows");
    }
    AnalysisCandidate result;
    result.diagnostics = {policies.version,
            "search plan supplied explicitly; portable arithmetic is not bit-exact original behavior",
            "beat phase only; four-beat/bass selection is a separate policy",
            "no variable-tempo inference from anchor interpolation"};
    if (cancelled && cancelled()) {
        result.status = AnalysisStatus::Cancelled;
        return result;
    }
    if (events.size() < config.minimum_events) {
        result.status = AnalysisStatus::InsufficientEvidence;
        return result;
    }
    const std::size_t windows = duration < config.window_seconds ? 1 :
            1 + static_cast<std::size_t>(std::floor(
                    (duration - config.window_seconds) / config.hop_seconds));
    if (events.size() > 100000000 / windows) {
        throw std::invalid_argument("local analysis exceeds event-window work budget");
    }
    std::vector<double> proposals;
    std::optional<double> previous_bpm;
    for (std::size_t window = 0; window < windows; ++window) {
        if (cancelled && cancelled()) {
            result.status = AnalysisStatus::Cancelled;
            return result;
        }
        const double start = window * config.hop_seconds;
        const double end = std::min(duration, start + config.window_seconds);
        ++result.local_windows;
        const auto groups = interval_votes(events, start, end);
        const LocalWindow context{start, end, events, groups, previous_bpm};
        const auto proposal = policies.local_selector(context,
                config.minimum_bpm, config.maximum_bpm);
        previous_bpm = proposal;
        if (proposal) {
            if (!std::isfinite(*proposal) || *proposal < config.minimum_bpm ||
                    *proposal > config.maximum_bpm) {
                throw std::invalid_argument("local policy returned invalid tempo");
            }
            proposals.push_back(*proposal);
        }
    }
    result.local_votes = proposals.size();
    const auto winner = strongest_tempo(tempo_consensus(proposals));
    if (!winner) return result;
    const auto seed = policies.octave_selector(winner->mean_bpm, events,
            config.minimum_bpm, config.maximum_bpm);
    if (!seed) return result;
    if (!std::isfinite(*seed) || *seed < config.minimum_bpm || *seed > config.maximum_bpm) {
        throw std::invalid_argument("octave policy returned invalid tempo");
    }
    if (cancelled && cancelled()) {
        result.status = AnalysisStatus::Cancelled;
        return result;
    }
    result.refinement = refine_tempo(events, *seed, config.search_plan);
    if (!result.refinement) return result;
    const auto& refined = *result.refinement;
    if (refined.bpm < config.minimum_bpm || refined.bpm > config.maximum_bpm) {
        result.diagnostics.push_back("refinement left configured BPM limits; candidate rejected");
        result.refinement.reset();
        return result;
    }
    const auto& final_histogram = refined.stages.back().histogram;
    const double peak = *std::max_element(final_histogram.bins.begin(), final_histogram.bins.end());
    if (final_histogram.total_weight <= 0 ||
            peak / final_histogram.total_weight < config.minimum_peak_fraction) {
        result.diagnostics.push_back("proposed concentration guard rejected diffuse evidence");
        return result;
    }
    const auto phase = policies.coarse_phase_selector(refined, events);
    if (!phase || !std::isfinite(*phase)) return result;
    const auto corrected = correct_phase(events, refined.bpm, *phase,
            PhaseWrapPolicy::CanonicalBeatPhase);
    if (cancelled && cancelled()) {
        result.status = AnalysisStatus::Cancelled;
        return result;
    }
    result.bpm = refined.bpm;
    result.beat_phase_seconds = corrected.phase_seconds;
    result.phase_support = corrected.support_count;
    result.status = AnalysisStatus::Candidate;
    result.diagnostics.push_back("candidate, not calibrated musical confidence or original equivalence");
    if (!corrected.support_count) {
        result.diagnostics.push_back("small correction unsupported; retained coarse phase");
    }
    return result;
}

